import{_ as e,o as f,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const u=JSON.parse('{"title":"التنقل: المترو والحافلات وسيارات الأجرة","description":"كيف تستخدم مترو الدوحة وترام لوسيل وحافلات مترولينك وحافلات كروة وسيارات أجرة كروة، وما التطبيقات والبطاقات التي تحتاج إليها.","frontmatter":{"title":"التنقل: المترو والحافلات وسيارات الأجرة","description":"كيف تستخدم مترو الدوحة وترام لوسيل وحافلات مترولينك وحافلات كروة وسيارات أجرة كروة، وما التطبيقات والبطاقات التي تحتاج إليها.","lastChecked":"2026-10","sourceCount":6},"headers":[],"relativePath":"ar/guide/transport.md","filePath":"ar/guide/transport.md"}'),t={name:"ar/guide/transport.md"};function s(n,a,l,i,c,p){return f(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="التنقل-المترو-والحافلات-وسيارات-الأجرة" tabindex="-1">التنقل: المترو والحافلات وسيارات الأجرة <a class="header-anchor" href="#التنقل-المترو-والحافلات-وسيارات-الأجرة" aria-label="Permalink to &quot;التنقل: المترو والحافلات وسيارات الأجرة&quot;">​</a></h1><p>يقوم النقل العام في قطر على مترو الدوحة، ويتصل به ترام لوسيل والحافلات المغذية. وتدير شركة مواصلات الحكومية، صاحبة علامة كروة، الحافلات العامة وسيارات أجرة كروة.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup><sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><h2 id="مترو-الدوحة" tabindex="-1">مترو الدوحة <a class="header-anchor" href="#مترو-الدوحة" aria-label="Permalink to &quot;مترو الدوحة&quot;">​</a></h2><p>للمترو ثلاثة خطوط تلتقي جميعها في محطة مشيرب:<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><ul><li><strong>الخط الأحمر:</strong> من الوكرة جنوبًا إلى لوسيل شمالًا، ويخدم أيضًا مطار حمد الدولي عند المبنى 1.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></li><li><strong>الخط الأخضر:</strong> من المنصورة شرقًا إلى الرفاع مول قطر غربًا.<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3]</a></sup></li><li><strong>الخط الذهبي:</strong> من رأس أبو عبود إلى العزيزية.<sup class="footnote-ref"><a href="#fn3" id="fnref3:3">[3]</a></sup></li></ul><p>وللسفر درجتان: الدرجة العادية، وتشمل عربات العائلات، ودرجة جولد كلوب.<sup class="footnote-ref"><a href="#fn3" id="fnref3:4">[3]</a></sup></p><p>يعمل المترو من الصباح الباكر حتى وقت متأخر، ويتوقف صباح الجمعة لأداء الصلاة. وقد تتغير المواعيد، فراجع موقع مترو الدوحة أو تطبيقه قبل الاعتماد على رحلة مبكرة أو متأخرة.<sup class="footnote-ref"><a href="#fn3" id="fnref3:5">[3]</a></sup></p><h2 id="التذاكر-وبطاقات-السفر" tabindex="-1">التذاكر وبطاقات السفر <a class="header-anchor" href="#التذاكر-وبطاقات-السفر" aria-label="Permalink to &quot;التذاكر وبطاقات السفر&quot;">​</a></h2><p>اشتر التذكرة من آلة البيع في أي محطة. أما بطاقة السفر فمخصصة لمن يستخدم المترو كثيرًا، وهي مصممة لإعادة الشحن.<sup class="footnote-ref"><a href="#fn3" id="fnref3:6">[3]</a></sup></p><p>وتصلح بطاقة السفر نفسها لمترو الدوحة وترام لوسيل ومترولينك ومترو إكسبريس.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup> وفي الترام، مرر البطاقة على أجهزة التحقق عند الصعود وعند النزول.<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup></p><p>لا تذكر هذه الصفحة الأسعار. استخدم رابط خيارات التذاكر في دليل المترو على موقع زوروا قطر لمعرفة الأسعار الحالية.<sup class="footnote-ref"><a href="#fn3" id="fnref3:7">[3]</a></sup></p><h2 id="ترام-لوسيل" tabindex="-1">ترام لوسيل <a class="header-anchor" href="#ترام-لوسيل" aria-label="Permalink to &quot;ترام لوسيل&quot;">​</a></h2><p>يتصل الترام بالمترو في محطتي لوسيل QNB ولقطيفية.<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4]</a></sup> ويذكر موقع زوروا قطر أن له أربعة خطوط و25 محطة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="مترولينك-ومترو-إكسبريس" tabindex="-1">مترولينك ومترو إكسبريس <a class="header-anchor" href="#مترولينك-ومترو-إكسبريس" aria-label="Permalink to &quot;مترولينك ومترو إكسبريس&quot;">​</a></h2><p>مترولينك هي شبكة الحافلات المغذية التي تنقل الركاب من محطات المترو وإليها.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup> ويصفها موقع زوروا قطر بأنها مجانية.<sup class="footnote-ref"><a href="#fn3" id="fnref3:8">[3]</a></sup> والمسارات تتغير، فقد أضافت مواصلات المسارين M307 وM308 بين محطتي السودان والمدينة الرياضية ابتداءً من 10 مايو 2026، فراجع تطبيق Karwa Journey Planner أو اتصل بالرقم 4458 8888.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></p><p>وفي مناطق معينة يمكنك أيضًا طلب رحلة مشتركة مجانية إلى أقرب محطة مترو أو ترام عبر تطبيق كروة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup> ويذكر دليل المترو على موقع زوروا قطر أيضًا خدمة الرحلات المشتركة مترو إكسبريس.<sup class="footnote-ref"><a href="#fn3" id="fnref3:9">[3]</a></sup></p><h2 id="حافلات-كروة" tabindex="-1">حافلات كروة <a class="header-anchor" href="#حافلات-كروة" aria-label="Permalink to &quot;حافلات كروة&quot;">​</a></h2><p>حافلات كروة هي شبكة الحافلات العامة التي تشغلها مواصلات.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup> ويتيح لك تطبيق حافلات كروة تخطيط رحلتك والاطلاع على الشبكة وإدارة بطاقاتك الذكية.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup> وتنشر مواصلات جميع مسارات الحافلات العامة على موقعها.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></p><h2 id="سيارات-الأجرة" tabindex="-1">سيارات الأجرة <a class="header-anchor" href="#سيارات-الأجرة" aria-label="Permalink to &quot;سيارات الأجرة&quot;">​</a></h2><p>سيارات أجرة كروة فيروزية اللون ويسهل تمييزها.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></p><ul><li><strong>الحجز:</strong> عبر تطبيق كروة للأجرة، أو الموقع الإلكتروني، أو مركز خدمة العملاء على مدار الساعة 4458 8888.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li><li><strong>الخيار الأقل تكلفة:</strong> الخدمة الاقتصادية، بالتعاون مع فوكس ترانسبورت، متاحة في تطبيق كروة للأجرة فقط.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li><strong>المساعدة:</strong> دعم العملاء متاح على مدار الساعة عبر الهاتف، ومتاح كذلك عبر واتساب.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li><li><strong>السيارات الأكبر أو الخاصة:</strong> يمكن حجز ليموزين الدوحة عبر تطبيق كروة أو الموقع الإلكتروني أو الرقم نفسه.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></li></ul><p>وتطبيق أوبر مستخدم على نطاق واسع أيضًا.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></p><h2 id="التطبيقات-المفيدة" tabindex="-1">التطبيقات المفيدة <a class="header-anchor" href="#التطبيقات-المفيدة" aria-label="Permalink to &quot;التطبيقات المفيدة&quot;">​</a></h2><ul><li><strong>تطبيق مترو الدوحة:</strong> لمعرفة المواعيد ومعلومات الخدمة.<sup class="footnote-ref"><a href="#fn3" id="fnref3:10">[3]</a></sup></li><li><strong>تطبيق كروة للأجرة:</strong> لسيارات الأجرة والخدمة الاقتصادية.<sup class="footnote-ref"><a href="#fn2" id="fnref2:5">[2]</a></sup></li><li><strong>تطبيق حافلات كروة:</strong> لرحلات الحافلات والبطاقات الذكية.<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5]</a></sup></li></ul><p>انظر أيضًا: <a href="./driving">القيادة</a>، <a href="./arriving-and-visas">الوصول والتأشيرات</a>.</p><h2 id="المصادر" tabindex="-1">المصادر <a class="header-anchor" href="#المصادر" aria-label="Permalink to &quot;المصادر&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>زوروا قطر، <a href="https://visitqatar.com/intl-en/plan-your-trip/getting-around" target="_blank" rel="noreferrer">التنقل في قطر</a>. آخر تحقق: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn2" class="footnote-item"><p>مواصلات (كروة)، <a href="https://www.mowasalat.com/our-service/taxi-limousine/" target="_blank" rel="noreferrer">خدمات أجرة كروة والليموزين</a>. آخر تحقق: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn3" class="footnote-item"><p>زوروا قطر، <a href="https://visitqatar.com/intl-en/plan-your-trip/getting-around/doha-metro" target="_blank" rel="noreferrer">دليل مترو الدوحة: التذاكر والخريطة وساعات الخدمة</a>. آخر تحقق: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:8" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:9" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:10" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn4" class="footnote-item"><p>وزارة النقل، <a href="https://mot.gov.qa/en/news/minister-transport-inaugurates-turquoise-line-lusail-tram-network" target="_blank" rel="noreferrer">وزير النقل يدشن الخط الفيروزي لشبكة ترام لوسيل</a>. آخر تحقق: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref4:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn5" class="footnote-item"><p>مواصلات (كروة)، <a href="https://www.mowasalat.com/" target="_blank" rel="noreferrer">مواصلات قطر</a>. آخر تحقق: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn6" class="footnote-item"><p>مواصلات (كروة)، <a href="https://www.mowasalat.com/mowasalat/public-transportation/" target="_blank" rel="noreferrer">النقل العام</a>. آخر تحقق: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li></ol></section>',28)])])}const b=e(t,[["render",s]]);export{u as __pageData,b as default};
